import{c as e,i as t,r as n,t as r}from"./app-KGVn0p9Q.js";var i=JSON.parse(`{"path":"/react/","title":"React 进阶：配置 Proxy 代理与 Cookie 跨域透传问题","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1789095025000,"contributors":[{"name":"5312","username":"5312","email":"1765080897@qq.com","commits":2,"url":"https://github.com/5312"},{"name":"tierlabx","username":"tierlabx","email":"1765080897@qq.com","commits":1,"url":"https://github.com/tierlabx"}],"changelog":[{"hash":"5cc5670be5a1eee4269379f5333d3c3fea7cf2a9","time":1789095025000,"email":"1765080897@qq.com","author":"tierlabx","message":"docs: 完善所有原有的空白文档并新增 Rust 学习指南"},{"hash":"7530f098317e51ccc2c7262cbebdf92e997ca1ff","time":1665310021000,"email":"1765080897@qq.com","author":"5312","message":"proxy 代理设置cookie问题"},{"hash":"aa3ecc50c8a9a40d25e7d10dbf57836b42db2dc5","time":1657763690000,"email":"1765080897@qq.com","author":"5312","message":"blog->>init"}]},"filePathRelative":"react/index.md"}`),a={name:`index.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="react-进阶-配置-proxy-代理与-cookie-跨域透传问题" tabindex="-1"><a class="header-anchor" href="#react-进阶-配置-proxy-代理与-cookie-跨域透传问题"><span>React 进阶：配置 Proxy 代理与 Cookie 跨域透传问题</span></a></h1><p>在 React 的日常开发中，我们通常会在本地启动一个 Dev Server（通常运行在 <code>localhost:3000</code>）。而我们的后端 API 接口可能部署在测试服务器或者开发服务器上。</p><p>当我们在本地浏览器直接请求这些跨域接口时，就会遇到<strong>跨域拦截 (CORS)</strong> 的问题。为了解决这个问题，在开发环境下我们通常会配置<strong>反向代理 (Proxy)</strong>。</p><h2 id="_1-基础配置-react-中的-proxy" tabindex="-1"><a class="header-anchor" href="#_1-基础配置-react-中的-proxy"><span>1. 基础配置：React 中的 Proxy</span></a></h2><p>对于由 <code>create-react-app</code> 创建的项目，最简单的 Proxy 配置方式是在 <code>package.json</code> 中添加一个 <code>proxy</code> 字段：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;name&quot;</span><span class="token operator">:</span> <span class="token string">&quot;my-app&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;version&quot;</span><span class="token operator">:</span> <span class="token string">&quot;0.1.0&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;proxy&quot;</span><span class="token operator">:</span> <span class="token string">&quot;http://api.backend.com&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;dependencies&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// ...</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>但如果是更复杂的代理需求（例如多代理路径，重写路径，修改响应头），我们需要使用 <code>http-proxy-middleware</code> 插件。</p><p>在 <code>src</code> 目录下新建 <code>setupProxy.js</code> 文件：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> <span class="token punctuation">{</span> createProxyMiddleware <span class="token punctuation">}</span> <span class="token operator">=</span> <span class="token function">require</span><span class="token punctuation">(</span><span class="token string">&#39;http-proxy-middleware&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">module<span class="token punctuation">.</span><span class="token function-variable function">exports</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">app</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">  app<span class="token punctuation">.</span><span class="token function">use</span><span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&#39;/api&#39;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token function">createProxyMiddleware</span><span class="token punctuation">(</span><span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">target</span><span class="token operator">:</span> <span class="token string">&#39;http://api.backend.com&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">changeOrigin</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span> <span class="token comment">// 控制服务器接收到的请求头中 host 字段的值</span></span>
<span class="line">      <span class="token literal-property property">pathRewrite</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token string-property property">&#39;^/api&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&#39;</span> <span class="token comment">// 将 /api 路径重写为空</span></span>
<span class="line">      <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">  <span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_2-核心痛点-proxy-代理后-cookie-丢失问题" tabindex="-1"><a class="header-anchor" href="#_2-核心痛点-proxy-代理后-cookie-丢失问题"><span>2. 核心痛点：Proxy 代理后 Cookie 丢失问题</span></a></h2><p>在代理配置成功后，接口确实可以调通了。但如果在项目中涉及到<strong>登录授权</strong>，且后端是通过向浏览器写入 Cookie（<code>Set-Cookie</code>）来维持 Session 状态时，你会发现一个奇怪的现象： <strong>接口返回 200 成功登录，但在随后的请求中，Cookie 并没有被携带上，导致状态校验失败。</strong></p><h3 id="原因分析" tabindex="-1"><a class="header-anchor" href="#原因分析"><span>原因分析</span></a></h3><p>这通常是由于后端在 <code>Set-Cookie</code> 时，指定了特定的 <code>Domain</code> 或 <code>Path</code>。</p><ul><li>如果后端的 <code>Path=/learning/</code>，而你本地项目请求的根路径是 <code>/</code>，浏览器会认为路径不匹配，从而拒绝保存该 Cookie。</li><li>或者是跨域问题导致的 domain 不匹配，导致浏览器丢弃了 Cookie。</li></ul><h3 id="解决方案-拦截响应并重写-cookie-路径" tabindex="-1"><a class="header-anchor" href="#解决方案-拦截响应并重写-cookie-路径"><span>解决方案：拦截响应并重写 Cookie 路径</span></a></h3><p>我们需要在 <code>setupProxy.js</code> (或者 Webpack/Umi 的 proxy 配置) 中，利用 <code>onProxyRes</code> 钩子函数，拦截服务器返回的响应，找到 <code>set-cookie</code> 字段，并将它里面限制过死的 <code>Path</code> 替换为根路径 <code>/</code>。</p><p>以下是针对 <code>Cookie Path</code> 不匹配的完美解决方案：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line">module<span class="token punctuation">.</span>exports <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">  <span class="token literal-property property">proxy</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token string-property property">&#39;/xd&#39;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">      <span class="token literal-property property">target</span><span class="token operator">:</span> <span class="token string">&#39;http://snce.xidian.edu.cn/&#39;</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">changeOrigin</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">      <span class="token literal-property property">pathRewrite</span><span class="token operator">:</span> <span class="token punctuation">{</span> <span class="token string-property property">&#39;^/xd&#39;</span><span class="token operator">:</span> <span class="token string">&#39;&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">      </span>
<span class="line">      <span class="token comment">// 当代理服务器接收到目标服务器的响应时触发</span></span>
<span class="line">      <span class="token function-variable function">onProxyRes</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">proxyRes<span class="token punctuation">,</span> req<span class="token punctuation">,</span> res</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 1. 获取服务器返回的 cookie 数组</span></span>
<span class="line">        <span class="token keyword">const</span> cookies <span class="token operator">=</span> proxyRes<span class="token punctuation">.</span>headers<span class="token punctuation">[</span><span class="token string">&#39;set-cookie&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">        </span>
<span class="line">        <span class="token comment">// 2. 定义我们要匹配并替换的路径正则</span></span>
<span class="line">        <span class="token keyword">const</span> cookiePathRegex <span class="token operator">=</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">Path=\\/learning\\/</span><span class="token regex-delimiter">/</span><span class="token regex-flags">i</span></span><span class="token punctuation">;</span> <span class="token comment">// 注意末尾不需要分号</span></span>
<span class="line">        </span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>cookies<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">          <span class="token comment">// 3. 遍历并修改每一条 cookie</span></span>
<span class="line">          <span class="token keyword">const</span> newCookie <span class="token operator">=</span> cookies<span class="token punctuation">.</span><span class="token function">map</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token parameter">cookieStr</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>cookiePathRegex<span class="token punctuation">.</span><span class="token function">test</span><span class="token punctuation">(</span>cookieStr<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">              <span class="token comment">// 将原特定的路径替换为根路径 &#39;/&#39;</span></span>
<span class="line">              <span class="token keyword">return</span> cookieStr<span class="token punctuation">.</span><span class="token function">replace</span><span class="token punctuation">(</span>cookiePathRegex<span class="token punctuation">,</span> <span class="token string">&#39;Path=/&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">            <span class="token keyword">return</span> cookieStr<span class="token punctuation">;</span></span>
<span class="line">          <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">          </span>
<span class="line">          <span class="token comment">// 4. 删除原有的 set-cookie 头</span></span>
<span class="line">          <span class="token keyword">delete</span> proxyRes<span class="token punctuation">.</span>headers<span class="token punctuation">[</span><span class="token string">&#39;set-cookie&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line">          <span class="token comment">// 5. 挂载我们修改后放宽权限的新 cookie</span></span>
<span class="line">          proxyRes<span class="token punctuation">.</span>headers<span class="token punctuation">[</span><span class="token string">&#39;set-cookie&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> newCookie<span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">      <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>通过重写 <code>set-cookie</code> 的 <code>Path</code>（必要时还可以重写 <code>Domain</code>），就可以欺骗浏览器，让它乖乖地在本地 localhost 环境下保存该 Cookie。当我们在本地发起下一次请求时，浏览器便会自动带上这个 Cookie，完美解决本地开发环境下的登录状态透传问题！</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};